gacn(){return"\u0623\u0646\u0645\u0627\u0637 \u062c\u0627\u0647\u0632\u0629 \u0644\u0623\u0646\u0648\u0627\u0639 \u062d\u0627\u0644\u0627\u062a \u062a\u064f\u0628\u0646\u0649 \u0645\u0639\u064b\u0627 \u062f\u0627\u0626\u0645\u064b\u0627 (\u0645\u062b\u0644 \u0627\u0644\u062f\u0639\u0627\u0645\u0629 \u0648\u0627\u0644\u062a\u0627\u062c) \u2014 \u0627\u062e\u062a\u0631\u0647\u0627 \u0641\u064a \u062d\u0627\u0644\u0629 \u062c\u062f\u064a\u062f\u0629 \u0644\u0625\u0646\u0634\u0627\u0621 \u0643\u0644 \u0646\u0648\u0639 \u062f\u0641\u0639\u0629 \u0648\u0627\u062d\u062f\u0629."},
gac_(){return"\u0627\u0644\u0633\u0645\u0627\u062d \u0628\u0627\u0644\u0627\u062e\u062a\u064a\u0627\u0631 \u0627\u0644\u062d\u0631"},
