ga1C(){return"\u06af\u06c6\u0695\u06cc\u0646\u06cc \u0644\u06c6\u06af\u06c6"},
ga1B(){return"\u0633\u0695\u06cc\u0646\u06d5\u0648\u06d5\u06cc \u0644\u06c6\u06af\u06c6"},
a1k(a){return"\u0628\u0627\u0631\u06a9\u0631\u062f\u0646\u06cc \u0644\u06c6\u06af\u06c6 \u0633\u06d5\u0631\u06a9\u06d5\u0648\u062a\u0648\u0648 \u0646\u06d5\u0628\u0648\u0648: "+a},
ga1j(){return"\u0644\u06c6\u06af\u06c6\u06a9\u06d5 \u0632\u06c6\u0631 \u06af\u06d5\u0648\u0631\u06d5\u06cc\u06d5 \u2014 \u062a\u06a9\u0627\u06cc\u06d5 \u0648\u06ce\u0646\u06d5\u06cc\u06d5\u06a9 \u0628\u06d5\u06a9\u0627\u0631\u0628\u0647\u06ce\u0646\u06d5 \u06a9\u06d5\u0645\u062a\u0631 \u0644\u06d5 2 \u0645\u06ce\u06af\u0627\u0628\u0627\u06cc\u062a."},
